"""Cross-corpus table of the four BEIR port runs (SciFact, FiQA: judged port2; NFCorpus, ArguAna: v9 port3). Generated from the saved files; nothing is typed by hand.
usage: python docs/evidence/v9_port_summary.py <out.md>"""
import csv, json, statistics, sys

RUNS = dict(scifact='kaggle/judged_port2_scifact', fiqa='kaggle/judged_port2_fiqa', nfcorpus='kaggle/judged_port3_nfcorpus', arguana='kaggle/judged_port3_arguana')
rd = lambda d, n: {r['fault']: r for r in csv.DictReader(open(f'{d}/{n}'))}
det = {k: rd(v, 'port_detector_gates.csv') for k, v in RUNS.items()}; sol = {k: rd(v, 'port_solved.csv') for k, v in RUNS.items()}; rep = {k: rd(v, 'port_repair_gates.csv') for k, v in RUNS.items()}
ver = {k: json.load(open(f'{v}/PORT_VERDICT.json')) for k, v in RUNS.items()}; faults = list(sol['scifact'])
cell = lambda k, f: ('--' if det[k][f]['auroc'] in ('', None) else '%.2f' % float(det[k][f]['auroc'])) + ('*' if sol[k][f]['solved'] == 'True' else '')
L = ['# Four BEIR corpora, one stack (e5-small-v2 + HNSW + BM25 + MiniLM reranker), the same 20 faults and gates', '', 'Generated by `docs/evidence/v9_port_summary.py`. `*` = solved (detector AND repair PASS). `--` = detector not trained (too few hard episodes).', '',
     '| Corpus | Run | Clean Hit@5 (test) | Detectors pass | Repairs pass | Solved (of 20) | Ports (>= 15) | Unsolved |', '|---|---|---|---|---|---|---|---|']
for k, v in ver.items():
    L.append(f"| {k} | {RUNS[k].split('/')[-1]} | {v['clean_hit5']['test']:.3f} | {v['detectors_pass']} | {v['repairs_pass']} | {v['solved_both']} | {v['suite_ports']} | {', '.join(v['not_solved'])} |")
L += ['', '## Held-out detector AUROC per fault', '', '| Fault | ' + ' | '.join(RUNS) + ' |', '|---|' + '---|' * len(RUNS)]
for f in faults: L.append(f'| {f} | ' + ' | '.join(cell(k, f) for k in RUNS) + ' |')
L += ['', '## Faults unsolved in more than one corpus']
cnt = {f: [k for k in RUNS if sol[k][f]['solved'] != 'True'] for f in faults}
for f, ks in cnt.items():
    if len(ks) > 1: L.append(f'- **{f}**: unsolved in {", ".join(ks)}')
L += ['', '## Held-out positives per detector (the gate floor is 20)']
for k in RUNS: L.append(f"- {k}: min {min(int(det[k][f]['n_pos_test']) for f in faults)}, median {int(statistics.median(int(det[k][f]['n_pos_test']) for f in faults))}")
L += ['', '## How many detectors are at the AUROC ceiling (>= 0.995)']
for k in RUNS: a = [float(det[k][f]['auroc']) for f in faults if det[k][f]['auroc'] not in ('', None)]; L.append(f'- {k}: {sum(x >= 0.995 for x in a)} of {len(a)} trained detectors')
L += ['', '## NFCorpus and ArguAna against SciFact and FiQA (faults solved in all three runs involved)']
for k in ('nfcorpus', 'arguana'):
    d = []
    for f in faults:
        if all(sol[c][f]['solved'] == 'True' for c in ('scifact', 'fiqa', k)): d.append(abs(float(det[k][f]['auroc']) - statistics.mean([float(det['scifact'][f]['auroc']), float(det['fiqa'][f]['auroc'])])))
    L.append(f'- {k}: {len(d)} faults compared; {sum(x <= 0.10 for x in d)} are within 0.10 AUROC of the SciFact/FiQA mean')
open(sys.argv[1], 'w').write('\n'.join(L) + '\n'); print('\n'.join(L))
